package com.master.bedtime.child;
import android.app.admin.DevicePolicyManager;import android.content.BroadcastReceiver;import android.content.Context;import android.content.Intent;import android.os.Build;import android.provider.Settings;
public class BootReceiver extends BroadcastReceiver { @Override public void onReceive(Context context,Intent intent){String action=intent==null?null:intent.getAction();if(!Intent.ACTION_BOOT_COMPLETED.equals(action)&&!Intent.ACTION_MY_PACKAGE_REPLACED.equals(action)&&!Intent.ACTION_USER_UNLOCKED.equals(action))return;boolean setup=context.getSharedPreferences("cfg",Context.MODE_PRIVATE).getBoolean("setup_complete",false);if(!setup)return;boolean active=context.getSharedPreferences("cfg",Context.MODE_PRIVATE).getBoolean("last_active",false);try{Intent service=new Intent(context,BedtimeMonitorService.class);if(Build.VERSION.SDK_INT>=Build.VERSION_CODES.O)context.startForegroundService(service);else context.startService(service);}catch(Exception ignored){}if(!active)return;DevicePolicyManager dpm=(DevicePolicyManager)context.getSystemService(Context.DEVICE_POLICY_SERVICE);boolean owner=dpm!=null&&dpm.isDeviceOwnerApp(context.getPackageName());if(owner){try{context.startActivity(new Intent(context,BedtimeLockActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP));return;}catch(Exception ignored){}}if(Settings.canDrawOverlays(context))try{BedtimeOverlay.show(context);}catch(Exception ignored){}} }
